package com.oms.messaging;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.amqp.rabbit.connection.CorrelationData;
import org.springframework.amqp.core.*;
import com.oms.common.tenant.TenantRouting;
import com.rabbitmq.client.Channel;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.oms.messaging.MessageOutbox.*;
class MessageDeliveryTest {
 MessageOutbox out;MessageRuntime runtime;MessageHandler handler;
 @BeforeEach void setup(){String url=System.getenv("MESSAGE_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/message_delivery_test?"));DriverManagerDataSource ds=new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD"));out=new MessageOutbox();out.db=new JdbcTemplate(ds);out.transactionManager=new DataSourceTransactionManager(ds);out.service="channel";out.db.update("DELETE FROM oms_message_attempt");out.db.update("DELETE FROM oms_message_outbox");runtime=new MessageRuntime();runtime.outbox=out;runtime.rabbit=mock(RabbitTemplate.class);runtime.tenants=mock(TenantRouting.class);handler=mock(MessageHandler.class);when(handler.type()).thenReturn("PRODUCT_PULL");when(handler.handle(anyString(),anyMap())).thenReturn(MessageHandler.Outcome.done("done"));runtime.handlers=Collections.singletonList(handler);}
 String event(){return out.enqueue("QM","PRODUCT_PULL",1,1,"PRODUCTPULL1","1:1",0);}
 @Test void businessTransactionRollbackDoesNotLeaveNotification(){out.tx(()->{event();return null;});out.db.update("DELETE FROM oms_message_outbox");assertThrows(RuntimeException.class,()->out.tx(()->{event();throw new RuntimeException("rollback");}));assertEquals(0,out.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox",Integer.class));}
 @Test void duplicateIdentityIsScopedByCompanyAndVersion(){String first=event();assertEquals(first,event());assertNotEquals(first,out.enqueue("OTHER","PRODUCT_PULL",1,1,"PRODUCTPULL1","1:1",0));assertNotEquals(first,out.enqueue("QM","PRODUCT_PULL",1,2,"PRODUCTPULL1","1:2",0));assertThrows(IllegalArgumentException.class,()->out.row("OTHER",first));assertEquals(3,out.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox",Integer.class));}
 @Test void redeliveryAfterCompletionNeverRunsBusinessAgain(){String e=event();Map<String,Object> row=out.row("QM",e);runtime.execute("QM",row,"MQ");runtime.execute("QM",row,"MQ");verify(handler,times(1)).handle(eq("QM"),anyMap());assertEquals("SUCCESS",out.row("QM",e).get("process_state"));}
 @Test void onlyOneCompetingWorkerOwnsLease()throws Exception {String e=event();Map<String,Object> row=out.row("QM",e);CountDownLatch entered=new CountDownLatch(1),finish=new CountDownLatch(1);when(handler.handle(anyString(),anyMap())).thenAnswer(i->{entered.countDown();assertTrue(finish.await(4,TimeUnit.SECONDS));return MessageHandler.Outcome.done("done");});ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> first=pool.submit(()->runtime.execute("QM",row,"MQ"));assertTrue(entered.await(3,TimeUnit.SECONDS));pool.submit(()->runtime.execute("QM",row,"COMPENSATION")).get(2,TimeUnit.SECONDS);finish.countDown();first.get(3,TimeUnit.SECONDS);verify(handler,times(1)).handle(eq("QM"),anyMap());}finally{finish.countDown();pool.shutdownNow();}}
 @Test void publisherRequiresConfirmAndNoReturn(){String e=event();doAnswer(i->{((CorrelationData)i.getArgument(3)).getFuture().set(new CorrelationData.Confirm(true,null));return null;}).when(runtime.rabbit).send(anyString(),anyString(),any(Message.class),any(CorrelationData.class));runtime.publish("QM",out.row("QM",e));assertEquals("PUBLISHED",out.row("QM",e).get("publish_state"));assertEquals("PENDING",out.row("QM",e).get("process_state"));}
 @Test void mandatoryReturnRemainsDurableAndCanUseCompensation(){String e=event();doAnswer(i->{CorrelationData cd=i.getArgument(3);cd.setReturned(new ReturnedMessage(i.getArgument(2),312,"NO_ROUTE","oms.work.v1","channel"));cd.getFuture().set(new CorrelationData.Confirm(true,null));return null;}).when(runtime.rabbit).send(anyString(),anyString(),any(Message.class),any(CorrelationData.class));runtime.publish("QM",out.row("QM",e));assertEquals("UNCERTAIN",out.row("QM",e).get("publish_state"));runtime.execute("QM",out.row("QM",e),"COMPENSATION");assertEquals("SKIPPED",out.row("QM",e).get("publish_state"));assertEquals("SUCCESS",out.row("QM",e).get("process_state"));}
 @Test void outageDoesNotStarveCompensationBehindPublisherRetries(){String e=event();out.db.update("UPDATE oms_message_outbox SET next_process_at=DATE_SUB(NOW(),INTERVAL 70 SECOND)");when(runtime.tenants.companies()).thenReturn(Collections.singleton("QM"));runtime.compensate();assertEquals("SUCCESS",out.row("QM",e).get("process_state"));verifyNoInteractions(runtime.rabbit);}
 @Test void fastConsumerAndLateConfirmDoNotEraseNextBusinessAttempt(){String e=event();when(handler.handle(anyString(),anyMap())).thenReturn(MessageHandler.Outcome.again("next page",5));doAnswer(i->{runtime.execute("QM",out.row("QM",e),"MQ");((CorrelationData)i.getArgument(3)).getFuture().set(new CorrelationData.Confirm(true,null));return null;}).when(runtime.rabbit).send(anyString(),anyString(),any(Message.class),any(CorrelationData.class));runtime.publish("QM",out.row("QM",e));Map<String,Object> row=out.row("QM",e);assertEquals("WAITING",row.get("process_state"));assertEquals("PENDING",row.get("publish_state"));assertEquals(0,n(row,"business_attempts"));runtime.execute("QM",row,"MQ");verify(handler,times(1)).handle(anyString(),anyMap());}
 @Test void manualAcknowledgementOccursOnlyAfterDurableResult()throws Exception {String e=event();Channel channel=mock(Channel.class);MessageProperties p=new MessageProperties();p.setDeliveryTag(10);Message m=new Message(new ObjectMapper().writeValueAsBytes(out.envelope(out.row("QM",e))),p);doAnswer(i->{assertEquals("SUCCESS",out.row("QM",e).get("process_state"));return null;}).when(channel).basicAck(10,false);runtime.consume(m,channel);verify(channel).basicAck(10,false);verify(channel,never()).basicReject(anyLong(),anyBoolean());}
 @Test void forgedEnvelopeIsRejectedWithoutBusinessOrCrossCompanyAccess()throws Exception {String e=event();Map<String,Object> body=out.envelope(out.row("QM",e));body.put("company_code","OTHER");MessageProperties p=new MessageProperties();p.setDeliveryTag(11);Channel channel=mock(Channel.class);runtime.consume(new Message(new ObjectMapper().writeValueAsBytes(body),p),channel);verify(channel).basicReject(11,false);verify(handler,never()).handle(anyString(),anyMap());assertEquals("PENDING",out.row("QM",e).get("process_state"));assertNull(com.baomidou.dynamic.datasource.toolkit.DynamicDataSourceContextHolder.peek());}
 @Test void expiredOwnerCannotOverwriteNewWorkerResult(){String e=event();assertTrue(out.claimWork("QM",e,"old","MQ"));out.db.update("UPDATE oms_message_outbox SET work_until=DATE_SUB(NOW(),INTERVAL 1 SECOND)");assertTrue(out.claimWork("QM",e,"new","MQ"));out.finish("QM",e,"new",MessageHandler.Outcome.done("new result"),"MQ",1);out.finish("QM",e,"old",MessageHandler.Outcome.failed("old result"),"MQ",1);assertEquals("SUCCESS",out.row("QM",e).get("process_state"));assertEquals("new result",out.row("QM",e).get("last_error"));}
 @Test void failedTaskRetryIsAuditedAndSuccessCannotBeReplayed(){String e=event();runtime.execute("QM",out.row("QM",e),"MQ");assertThrows(IllegalArgumentException.class,()->runtime.retry("QM",e,"tester","checked"));out.db.update("UPDATE oms_message_outbox SET process_state='FAILED' WHERE event_id=?",e);runtime.retry("QM",e,"tester","checked");verify(handler).replay(eq("QM"),anyMap(),eq("tester"),eq("checked"));assertEquals(1,out.db.queryForObject("SELECT COUNT(*) FROM oms_message_attempt WHERE stage='RETRY'",Integer.class));assertThrows(IllegalArgumentException.class,()->runtime.retry("QM",e,"tester",""));}
 @Test void laterNotificationPreventsRepeatedManualReplayOfOriginalFailure(){String e=event();out.db.update("UPDATE oms_message_outbox SET process_state='FAILED'");out.enqueue("QM","PRODUCT_PULL",1,2,"PRODUCTPULL1","1:2",0);assertEquals(1,n(out.row("QM",e),"has_newer"));assertThrows(IllegalArgumentException.class,()->runtime.retry("QM",e,"tester","checked"));verify(handler,never()).replay(anyString(),anyMap(),anyString(),anyString());}
 @Test void pausedQueuePreventsMqAndCompensationFromClaimingBusinessWork(){String e=event();QueueSupervisor q=new QueueSupervisor();QueueSupervisor.State state=new QueueSupervisor.State();state.accepting=false;q.states.put("PRODUCT_PULL",state);org.springframework.beans.factory.ObjectProvider<QueueSupervisor> provider=mock(org.springframework.beans.factory.ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(q);runtime.supervisors=provider;when(runtime.tenants.companies()).thenReturn(Collections.singleton("QM"));try{assertFalse(runtime.execute("QM",out.row("QM",e),"MQ"));out.db.update("UPDATE oms_message_outbox SET next_process_at=DATE_SUB(NOW(),INTERVAL 120 SECOND)");runtime.compensate();verify(handler,never()).handle(anyString(),anyMap());assertEquals("PENDING",out.row("QM",e).get("process_state"));}finally{q.scheduler.shutdownNow();q.consumers.shutdownNow();}}
 @Test void stalePublisherCandidateCannotRepublishAFreshConfirmation(){String e=event();Map<String,Object> candidate=out.row("QM",e);out.db.update("UPDATE oms_message_outbox SET publish_state='PUBLISHED',last_published_at=NOW(3),next_publish_at=DATE_SUB(NOW(3),INTERVAL 1 SECOND) WHERE event_id=?",e);runtime.publish("QM",candidate);verifyNoInteractions(runtime.rabbit);assertEquals(0,n(out.row("QM",e),"send_attempts"));}
}
